# Let me try the standard Kimpel Products problem
# Activities, predecessors, and durations

# Common version of this problem:
# Activity | Predecessor | Time
# A        | -           | 3
# B        | A           | 2
# C        | A           | 4
# D        | A           | 4
# E        | B           | 6
# F        | C           | 6
# G        | D,E,F       | 2

activities = {
    'A': {'pred': [], 'dur': 3},
    'B': {'pred': ['A'], 'dur': 2},
    'C': {'pred': ['A'], 'dur': 4},
    'D': {'pred': ['A'], 'dur': 4},
    'E': {'pred': ['B'], 'dur': 6},
    'F': {'pred': ['C'], 'dur': 6},
    'G': {'pred': ['D', 'E', 'F'], 'dur': 2},
}

# Forward pass - Early Start (ES) and Early Finish (EF)
order = ['A', 'B', 'C', 'D', 'E', 'F', 'G']

ES = {}
EF = {}

for act in order:
    preds = activities[act]['pred']
    if not preds:
        ES[act] = 0
    else:
        ES[act] = max(EF[p] for p in preds)
    EF[act] = ES[act] + activities[act]['dur']

print("Forward Pass:")
for act in order:
    print(f"{act}: ES={ES[act]}, EF={EF[act]}")

project_completion = EF['G']
print(f"\nProject completion time: {project_completion}")

# Backward pass - Late Start (LS) and Late Finish (LF)
LF = {}
LS = {}

# Find successors
successors = {act: [] for act in order}
for act in order:
    for p in activities[act]['pred']:
        successors[p].append(act)

for act in reversed(order):
    if not successors[act]:
        LF[act] = project_completion
    else:
        LF[act] = min(LS[s] for s in successors[act])
    LS[act] = LF[act] - activities[act]['dur']

print("\nBackward Pass:")
for act in order:
    print(f"{act}: LS={LS[act]}, LF={LF[act]}")

# Slack
print("\nSlacks:")
slacks = []
for act in order:
    slack = LS[act] - ES[act]
    slacks.append(slack)
    print(f"{act}: Slack = {slack}")

print(f"\nSlacks in order: {slacks}")
"}

